162  rnp_result_t
   163  transferable_subkey_from_key(pgp_transferable_subkey_t *dst, const pgp_key_t *key)
   164  {
   165      pgp_source_t memsrc = {};
   166      rnp_result_t ret = RNP_ERROR_GENERIC;
   167
   168      if (!rnp_key_to_src(key, &memsrc)) {
   169          return RNP_ERROR_BAD_STATE;
   170      }
   171
   172      ret = process_pgp_subkey(&memsrc, dst, false);
   173      src_close(&memsrc);
   174      return ret;
   175  }
