   177  rnp_result_t
   178  transferable_subkey_merge(pgp_transferable_subkey_t *dst, const pgp_transferable_subkey_t *src)
   179  {
   180      rnp_result_t ret = RNP_ERROR_GENERIC;
   181
   182      if (!key_pkt_equal(&dst->subkey, &src->subkey, true)) {
   183          RNP_LOG("wrong subkey merge call");
   184          return RNP_ERROR_BAD_PARAMETERS;
   185      }
   186
   187      if ((ret = merge_signatures(&dst->signatures, &src->signatures))) {
   188          RNP_LOG("failed to merge signatures");
   189      }
   190      return ret;
   191  }
