   193  bool
   194  transferable_key_copy(pgp_transferable_key_t *      dst,
   195                        const pgp_transferable_key_t *src,
   196                        bool                          pubonly)
   197  {
   198      memset(dst, 0, sizeof(*dst));
   199
   200      if (!copy_key_pkt(&dst->key, &src->key, pubonly)) {
   201          RNP_LOG("failed to copy key pkt");
   202          goto error;
   203      }
   204
   205      for (list_item *uid = list_front(src->userids); uid; uid = list_next(uid)) {
   206          pgp_transferable_userid_t *tuid =
   207            (pgp_transferable_userid_t *) list_append(&dst->userids, NULL, sizeof(*tuid));
   208          if (!tuid || !transferable_userid_copy(tuid, (pgp_transferable_userid_t *) uid)) {
   209              RNP_LOG("failed to copy uid");
   210              goto error;
   211          }
   212      }
   213
   214      for (list_item *skey = list_front(src->subkeys); skey; skey = list_next(skey)) {
   215          pgp_transferable_subkey_t *tskey =
   216            (pgp_transferable_subkey_t *) list_append(&dst->subkeys, NULL, sizeof(*tskey));
   217          if (!tskey ||
   218              !transferable_subkey_copy(tskey, (pgp_transferable_subkey_t *) skey, pubonly)) {
   219              RNP_LOG("failed to copy subkey");
   220              goto error;
   221          }
   222      }
   223
   224      if (!copy_signatures(&dst->signatures, &src->signatures)) {
   225          RNP_LOG("failed to copy key signatures");
   226          goto error;
   227      }
   228      return true;
   229  error:
   230      transferable_key_destroy(dst);
